import subprocess
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

# Configuration
ALLOWED_REPORTS = ['sales', 'inventory', 'payroll', 'audit']
REPORT_DIR = '/opt/reports'

def sanitize_filename(name):
    """Remove path separators but allow other characters for report names"""
    # Strip directory traversal attempts
    name = name.replace('/', '').replace('\\', '')
    return name

def get_report_format(fmt):
    """Validate report format"""
    valid_formats = ['pdf', 'csv', 'xlsx']
    if fmt not in valid_formats:
        return 'pdf'
    return fmt

@app.route('/api/v2/reports/generate', methods=['POST'])
def generate_report():
    """Generate a report using the reporting engine"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request body'}), 400

    report_name = data.get('report_name', '')
    date_range = data.get('date_range', 'last_30d')
    output_format = get_report_format(data.get('format', 'pdf'))
    filters = data.get('filters', '')

    # Validate report name
    if not report_name or report_name not in ALLOWED_REPORTS:
        return jsonify({'error': 'Invalid report name'}), 400

    # Sanitize the date range parameter
    if not date_range.replace('_', '').replace('-', '').isalnum():
        return jsonify({'error': 'Invalid date range format'}), 400

    # Build the report generation command
    # The reporting engine binary accepts these arguments
    cmd = f'/opt/reporting-engine/bin/generate --report {report_name} --range {date_range} --format {output_format} --output {REPORT_DIR}/{report_name}.{output_format}'

    # Append optional filters if provided
    if filters:
        # Filters are passed as-is to support complex query expressions
        # e.g., "department=engineering&region=us-west"
        cmd += f' --filter "{filters}"'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=REPORT_DIR
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Report generation failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:200]
            }), 500

        return jsonify({
            'status': 'success',
            'report_path': f'/reports/{report_name}.{output_format}',
            'size_bytes': os.path.getsize(f'{REPORT_DIR}/{report_name}.{output_format}') if os.path.exists(f'{REPORT_DIR}/{report_name}.{output_format}') else 0
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/v2/reports/list', methods=['GET'])
def list_reports():
    """List available report files"""
    try:
        files = os.listdir(REPORT_DIR)
        return jsonify({'reports': [f for f in files if not f.startswith('.')]})
    except Exception:
        return jsonify({'reports': []})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
